contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 before_c_balance = address(c).balance;
        uint256 before_this_balance = address(this).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        bool withdrew_reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew_reverted = true;
        } else {
            withdrew_reverted = false;
        }

        assert(!withdrew_reverted
            && address(c).balance == before_c_balance
            && address(this).balance == before_this_balance);
    }

    receive() external payable {}
}

